SBQQ__Formula__c:
/* Tiered partner discounts */
IF(
    SBQQ__ProductFamily__c = "Software" &&
    SBQQ__Quantity__c >= 10,
    SBQQ__ListPrice__c * 0.90,
    SBQQ__ListPrice__c
)

/* Enterprise customer adjustment */
IF(
    SBQQ__Account__r.Segment__c = "Enterprise",
    Price * 0.97,
    Price
)

/* Special promotion */
IF(
    SBQQ__PromoCode__c = "Q4BUNDLE",
    Price * 0.85,
    Price
)
